import { activityRequest } from "../_shared/activities.ts";
import { canonicalize, validStructure, toHeightMap } from "../../../shared/blocks.ts";
import { applyAttempt, INITIAL_ATTEMPT } from "../../../shared/attempts.ts";
import {
  type ProblemGiven,
  type ProblemAnswer,
  type StudentSubmission,
  DIRECTIONS,
  type ProblemType,
  type RevealedAnswer,
} from "../../../shared/types.ts";
import { SEED_PROBLEMS } from "../../../shared/seedProblems.ts";
import { generatePracticeProblems, recommendedPracticeCount } from "../../../shared/practiceGenerator.ts";
import { conceptTagsForProblemType } from "../../../shared/problemMetadata.ts";
import { grade as gradeShared } from "../../../shared/grading.ts";
import { serviceClient, requireTeacher, teacherOwnsClass } from "../_shared/db.ts";
import {
  fail,
  handlePreflight,
  json,
  ok,
  readJson,
  text,
} from "../_shared/http.ts";
import {
  generatePin,
  generateClassCode,
  generateShareCode,
  hashPin,
  hashToken,
  verifySessionToken,
} from "../_shared/security.ts";

type Action =
  | "asset"
  | "home"
  | "lessonProblems"
  | "practice:new-set"
  | "problem"
  | "attempt"
  | "snapshot"
  | "snapshot:get"
  | "share:create"
  | "teacher:classes"
  | "teacher:class-upsert"
  | "teacher:students:list"
  | "teacher:students:create"
  | "teacher:students:update"
  | "teacher:students:pin-reset"
  | "teacher:students:toggle"
  | "teacher:lessons:list"
  | "teacher:lessons:set-lock"
  | "teacher:problems:list"
  | "teacher:problems:set-active";

interface BaseBody {
  action?: string;
}

interface DbProblemRow {
  image_path?: string | null;
  id: string;
  class_id: string | null;
  lesson: number;
  order_index: number;
  problem_type: ProblemType;
  title: string;
  prompt: string;
  grid_width: number;
  grid_depth: number;
  max_height: number;
  given_blocks: unknown;
  start_blocks: unknown;
  given: ProblemGiven;
  choices: unknown;
  answer: unknown;
  grading_mode: "exact" | "constraint";
  hint: string;
  explanation: string;
  difficulty: 1 | 2 | 3;
  xp: number;
  active: boolean;
  code: string | null;
}

interface ClassRow {
  id: string;
  name: string;
  class_code: string;
}

interface StudentRow {
  id: string;
  class_id: string;
  name: string;
  student_no: number | null;
  pin_hash: string;
  status: "active" | "disabled";
}

interface AttemptRow {
  id: string;
  wrong_count: number;
  hint_shown: boolean;
  answer_revealed: boolean;
  completed: boolean;
  attempt_count: number;
}

interface StudentCtx {
  studentId: string;
  classId: string;
}

const KNOWN_PROBLEM_TYPES: ProblemType[] = [
  "FREE_BUILD",
  "BLOCK_POSITION",
  "CAMERA_DIRECTION",
  "PROJECTION_DRAW",
  "COUNT",
  "COUNT_AMBIGUOUS",
  "BUILD_FROM_VIEWS",
  "BUILD_FROM_HEIGHTMAP",
  "HEIGHTMAP_FROM_BUILD",
  "BUILD_FROM_LAYERS",
  "LAYER_DRAW",
  "PATTERN_NEXT",
  "CHOICE",
];

function toInt(v: unknown): number | null {
  const n = Number(v);
  return Number.isFinite(n) && n > 0 ? Math.floor(n) : null;
}

function safeJson<T>(value: unknown, fallback: T): T {
  if (!value || typeof value !== "object") return fallback;
  return value as T;
}

function parseProblemType(value: unknown): ProblemType {
  if (typeof value === "string" && KNOWN_PROBLEM_TYPES.includes(value as ProblemType)) {
    return value as ProblemType;
  }
  return "BLOCK_POSITION";
}

function canonicalizeProblemBlocks(value: unknown): { x: number; y: number; z: number }[] {
  if (!Array.isArray(value)) return [];
  return canonicalize(value.filter((item) => {
    return (
      item &&
      typeof item === "object" &&
      Number.isFinite(Number((item as { x?: unknown }).x)) &&
      Number.isFinite(Number((item as { y?: unknown }).y)) &&
      Number.isFinite(Number((item as { z?: unknown }).z))
    );
  }).map((item) => ({
    x: Number((item as { x: number }).x),
    y: Number((item as { y: number }).y),
    z: Number((item as { z: number }).z),
  })));
}

function parseProblemRow(row: DbProblemRow | null) {
  if (!row) return null;
  const grid = {
    gridWidth: Number(row.grid_width ?? 4),
    gridDepth: Number(row.grid_depth ?? 4),
    maxHeight: Number(row.max_height ?? 4),
  };

  const given = safeJson<ProblemGiven>(row.given, {});
  const generator = (given as ProblemGiven & { _generator?: Record<string, unknown> })._generator;
  const answer = safeJson(row.answer, { kind: "count", value: 0 }) as {
    kind: "blocks" | "count" | "direction" | "choice" | "projections" | "heightMap" | "layers";
    blocks?: unknown;
    value?: unknown;
    direction?: unknown;
    index?: unknown;
    projections?: unknown;
    heightMap?: unknown;
    layers?: unknown;
  };

  const prompt = text(row.prompt, 3000);
  const safeChoices = Array.isArray(row.choices) ? row.choices.map((choice) => String(choice ?? "")) : [];
  const answerMeta = normalizeSubmission(answer);
  if (!answerMeta) return null;
  const problemType = parseProblemType(row.problem_type);

  return {
    id: row.id,
    stage: Number(row.order_index ?? 0) <= 1 ? "concept" : Number(row.order_index ?? 0) === 2 ? "check" : "more",
    hasImage: Boolean(row.image_path),
    templateId: typeof generator?.templateId === "string" ? generator.templateId : undefined,
    seed: Number.isInteger(generator?.seed) ? Number(generator?.seed) : undefined,
    generatorVersion: Number.isInteger(generator?.generatorVersion) ? Number(generator?.generatorVersion) : undefined,
    difficultyTier: typeof generator?.difficultyTier === "string" ? generator.difficultyTier : undefined,
    conceptTags: Array.isArray(generator?.conceptTags) ? generator.conceptTags.map(String) : conceptTagsForProblemType(problemType),
    sourceType: typeof generator?.sourceType === "string" ? generator.sourceType : (String(row.code ?? '').startsWith('GEN-L') ? 'GENERATED_PRACTICE' : (row.class_id ? 'TEACHER_CREATED' : (Number(row.order_index ?? 0) <= 2 ? 'BUILT_IN_CONCEPT' : 'BUILT_IN_WORKBOOK_STYLE'))),
    lesson: Number(row.lesson),
    orderIndex: Number(row.order_index ?? 0),
    problemType,
    title: String(row.title ?? ""),
    prompt,
    grid,
    givenBlocks: canonicalizeProblemBlocks(row.given_blocks),
    startBlocks: canonicalizeProblemBlocks(row.start_blocks),
    given,
    choices: safeChoices,
    gradingMode: (row.grading_mode === "constraint" ? "constraint" : "exact") as "exact" | "constraint",
    hint: String(row.hint ?? ""),
    explanation: String(row.explanation ?? ""),
    difficulty: Number(row.difficulty ?? 2) as 1 | 2 | 3,
    xp: Number(row.xp ?? 30),
    answer: answerMeta,
    code: row.code,
    active: Boolean(row.active),
    _raw: row,
  };
}

function buildRevealedAnswer(row: ReturnType<typeof parseProblemRow>): RevealedAnswer | null {
  if (!row) return null;

  if (row.answer.kind === "blocks") {
    return {
      blocks: row.answer.blocks,
      explanation: row.explanation ?? null,
    };
  }

  if (row.answer.kind === "count") {
    return {
      count: Number(row.answer.value ?? 0),
      explanation: row.explanation ?? null,
    };
  }

  if (row.answer.kind === "direction") {
    return {
      direction: String(row.answer.value ?? "front") as RevealedAnswer["direction"],
      explanation: row.explanation ?? null,
    };
  }

  if (row.answer.kind === "choice") {
    return {
      choiceIndex: Number(row.answer.index ?? 0),
      explanation: row.explanation ?? null,
    };
  }

  if (row.answer.kind === "projections") {
    return {
      projections: row.answer.projections ?? {},
      explanation: row.explanation ?? null,
    };
  }

  if (row.answer.kind === "heightMap") {
    return {
      heightMap: row.answer.heightMap ?? [],
      explanation: row.explanation ?? null,
    };
  }

  if (row.answer.kind === "layers") {
    return {
      layers: row.answer.layers ?? [],
      explanation: row.explanation ?? null,
    };
  }

  return {
    explanation: row.explanation ?? null,
  };
}

function parseSeedProblem(raw: (typeof SEED_PROBLEMS)[number]) {
  return {
    id: `seed:${raw.code}`,
    stage: raw.stage ?? (raw.orderIndex <= 1 ? "concept" : raw.orderIndex === 2 ? "check" : "more"),
    hasImage: false,
    templateId: raw.templateId,
    seed: raw.seed,
    generatorVersion: raw.generatorVersion,
    difficultyTier: raw.difficultyTier,
    conceptTags: raw.conceptTags ?? conceptTagsForProblemType(raw.problemType),
    sourceType: raw.sourceType ?? (raw.orderIndex <= 2 ? 'BUILT_IN_CONCEPT' : 'BUILT_IN_WORKBOOK_STYLE'),
    lesson: raw.lesson,
    orderIndex: raw.orderIndex,
    problemType: raw.problemType,
    title: raw.title,
    prompt: raw.prompt,
    grid: raw.grid,
    givenBlocks: canonicalize(raw.givenBlocks),
    startBlocks: canonicalize(raw.startBlocks),
    given: raw.given,
    choices: raw.choices,
    gradingMode: raw.gradingMode,
    hint: raw.hint,
    explanation: raw.explanation,
    difficulty: raw.difficulty,
    xp: raw.xp,
    answer: raw.answer,
    code: raw.code,
    active: true,
    _raw: null,
  };
}

function sanitizeToStudentProblem(row: ReturnType<typeof parseProblemRow> | ReturnType<typeof parseSeedProblem>) {
  if (!row) return null;
  return {
    id: row.id,
    stage: row.stage,
    hasImage: row.hasImage,
    templateId: row.templateId,
    seed: row.seed,
    generatorVersion: row.generatorVersion,
    difficultyTier: row.difficultyTier,
    conceptTags: row.conceptTags,
    sourceType: row.sourceType,
    lesson: row.lesson,
    orderIndex: row.orderIndex,
    problemType: row.problemType,
    title: row.title,
    prompt: row.prompt,
    givenBlocks: row.givenBlocks,
    startBlocks: row.startBlocks,
    grid: row.grid,
    choices: row.choices,
    given: row.given,
    difficulty: row.difficulty,
    xp: row.xp,
    hint: row.hint ? row.hint : null,
  };
}

function safeLessonRows(db: unknown[]): number[] {
  if (!Array.isArray(db)) return [];
  return db
    .map((row) => Number((row as { lesson?: unknown }).lesson))
    .filter((value) => Number.isInteger(value) && value >= 1 && value <= 12);
}

function makeDefaultLessonSettings(classId: string): Array<{ class_id: string; lesson: number; locked: boolean; practice_count: number | null }> {
  return Array.from({ length: 12 }, (_, index) => ({
    class_id: classId,
    lesson: index + 1,
    locked: index === 0 ? false : true,
    practice_count: null,
  }));
}

function countProblemsFromRows(rows: DbProblemRow[]): Record<number, number> {
  const counts: Record<number, number> = Object.fromEntries(Array.from({ length: 12 }, (_, idx) => [idx + 1, 0]));
  for (const row of rows) {
    if (row.lesson >= 1 && row.lesson <= 12 && row.active) {
      counts[row.lesson] = (counts[row.lesson] ?? 0) + 1;
    }
  }
  return counts;
}

function practiceSeedForStudent(studentId:string, lesson:number):number {
  let hash=lesson;
  for(const char of studentId) hash=((hash*31)+char.charCodeAt(0))|0;
  return Math.abs(hash)%1000000;
}
function belongsToStudentPractice(row:DbProblemRow,studentId:string):boolean {
  const code=String(row.code??'');
  if(!code.startsWith('GEN-L'))return true;
  const match=/^GEN-L(\d+)-S(\d+)-/.exec(code);
  return Boolean(match&&Number(match[2])===practiceSeedForStudent(studentId,Number(match[1])));
}

function generatedInsertRow(seed:(typeof SEED_PROBLEMS)[number]) {
  return { class_id:null, created_by:null, code:seed.code, lesson:seed.lesson, order_index:seed.orderIndex, problem_type:seed.problemType, title:seed.title, prompt:seed.prompt, grid_width:seed.grid.gridWidth, grid_depth:seed.grid.gridDepth, max_height:seed.grid.maxHeight, given_blocks:seed.givenBlocks, start_blocks:seed.startBlocks, given:{...seed.given,_generator:{templateId:seed.templateId,seed:seed.seed,generatorVersion:seed.generatorVersion,difficultyTier:seed.difficultyTier,conceptTags:seed.conceptTags,sourceType:seed.sourceType}}, choices:seed.choices, answer:seed.answer, grading_mode:seed.gradingMode, hint:seed.hint, explanation:seed.explanation, difficulty:seed.difficulty, xp:seed.xp, active:true };
}

function normalizeSubmission(raw: unknown): StudentSubmission | null {
  if (!raw || typeof raw !== "object") return null;
  const value = raw as Record<string, unknown>;
  const isGrid = (g: unknown, numeric = false): boolean => Array.isArray(g) && g.length <= 8 && g.every(row => Array.isArray(row) && row.length <= 8 && row.every(cell => numeric ? Number.isInteger(cell) && Number(cell) >= 0 && Number(cell) <= 8 : typeof cell === "boolean"));
  switch (value.kind) {
    case "blocks":
      if (!Array.isArray(value.blocks) || value.blocks.length > 512 || !value.blocks.every(b => b && Number.isInteger(b.x) && Number.isInteger(b.y) && Number.isInteger(b.z))) return null;
      return {kind:"blocks",blocks:value.blocks};
    case "count": return Number.isInteger(value.value) && Number(value.value) >= 0 ? {kind:"count",value:Number(value.value)} : null;
    case "direction": {
      const direction = value.direction ?? value.value;
      return DIRECTIONS.includes(direction as typeof DIRECTIONS[number]) ? {kind:"direction",value:direction as typeof DIRECTIONS[number]} : null;
    }
    case "choice": return Number.isInteger(value.index) && Number(value.index) >= 0 ? {kind:"choice",index:Number(value.index)} : null;
    case "heightMap": return isGrid(value.heightMap, true) ? {kind:"heightMap",heightMap:value.heightMap as number[][]} : null;
    case "layers": return Array.isArray(value.layers) && value.layers.length <= 8 && value.layers.every(layer => isGrid(layer)) ? {kind:"layers",layers:value.layers as boolean[][][]} : null;
    case "projections": {
      if (!value.projections || typeof value.projections !== "object") return null;
      const projections = value.projections as Record<string, unknown>;
      if (!Object.keys(projections).length || Object.entries(projections).some(([face, g]) => !["top","front","side"].includes(face) || !isGrid(g))) return null;
      return {kind:"projections",projections:projections as Partial<import("../../../shared/types.ts").Projections>};
    }
    default: return null;
  }
}

async function requireStudent(req: Request, db = serviceClient()): Promise<StudentCtx | Response> {
  const token = req.headers.get("x-student-token");
  if (!token) return fail(401, "SESSION_MISSING", "학생 세션 토큰이 없습니다.");

  const payload = await verifySessionToken(token);
  if (!payload) return fail(401, "SESSION_INVALID", "학생 세션이 만료되었거나 유효하지 않습니다.");

  const tokenHash = await hashToken(token);
  const { data: sessionRow, error } = await db
    .from("sb_student_sessions")
    .select("student_id, class_id, revoked")
    .eq("token_hash", tokenHash)
    .eq("revoked", false)
    .gt("expires_at", new Date().toISOString())
    .single();

  if (error || !sessionRow) {
    return fail(401, "SESSION_NOT_FOUND", "세션이 만료되었거나 유효하지 않습니다.");
  }

  if (sessionRow.student_id !== payload.sid || sessionRow.class_id !== payload.cid) {
    return fail(403, "SESSION_MISMATCH", "세션 정보가 일치하지 않습니다.");
  }

  const { data: student } = await db.from("sb_students").select("status").eq("id", sessionRow.student_id).eq("class_id", sessionRow.class_id).maybeSingle();
  if (!student || student.status !== "active") return fail(403, "STUDENT_DISABLED", "학생 계정을 확인해 주세요.");
  return { studentId: String(sessionRow.student_id), classId: String(sessionRow.class_id) };
}

function defaultHomePayload(): {
  className: string;
  classId: string;
  rewards: { totalXp: number; totalStars: number; badges: unknown[]; streak: number };
  lessons: Array<{ lesson: number; locked: boolean; totalProblems: number; completedProblems: number; stars: number; completed: boolean }>;
} {
  return {
    className: "",
    classId: "",
    rewards: { totalXp: 0, totalStars: 0, badges: [], streak: 0 },
    lessons: [],
  };
}

function normalizeAttemptState(row: AttemptRow | null) {
  return {
    wrongCount: row?.wrong_count ?? 0,
    hintShown: row?.hint_shown ?? false,
    answerRevealed: row?.answer_revealed ?? false,
    completed: row?.completed ?? false,
    attemptCount: row?.attempt_count ?? 0,
  };
}

Deno.serve(async (req: Request) => {
  const cors = handlePreflight(req);
  if (cors) return cors;

  if (req.method !== "POST") {
    return fail(405, "METHOD_NOT_ALLOWED", "POST 로만 호출할 수 있습니다.");
  }

  let db: Awaited<ReturnType<typeof serviceClient>>;
  try {
    db = serviceClient();
  } catch (error) {
    return fail(500, "CONFIG", error instanceof Error ? error.message : "설정 오류");
  }

  const body = await readJson(req);
  const action = text(body.action, 40) as Action;

  // 학생 동작
  if (action === "asset" || action.startsWith("activity:") || action === "home" || action === "lessonProblems" || action === "practice:new-set" || action === "problem" || action === "attempt" || action === "snapshot" || action === "snapshot:get") {
    const studentSession = await requireStudent(req, db);
    if (studentSession instanceof Response) return studentSession;

    if (action.startsWith("activity:")) return activityRequest(db, body, studentSession);

    if (action !== "home") {
      let targetLesson = toInt(body.lesson);
      if (action !== "lessonProblems" && action !== "practice:new-set") {
        const targetId = text(body.problemId, 80);
        const { data: target } = await db.from("sb_problems").select("lesson,active,class_id,grid_width,grid_depth,max_height")
          .eq("id", targetId).or(`class_id.eq.${studentSession.classId},class_id.is.null`).maybeSingle();
        if (!target || !target.active) return fail(404, "PROBLEM_NOT_FOUND", "문제를 찾을 수 없어요.");
        targetLesson = target.lesson;
        if (action === "snapshot") {
          if (!validStructure(body.blocks as { x: number; y: number; z: number }[], { gridWidth: target.grid_width, gridDepth: target.grid_depth, maxHeight: target.max_height })) {
            return fail(400, "INVALID_BLOCKS", "올바른 블록 좌표가 아닙니다.");
          }
          body.lesson = target.lesson;
          body.gridWidth = target.grid_width; body.gridDepth = target.grid_depth; body.maxHeight = target.max_height;
        }
      }
      if (!Number.isInteger(targetLesson) || !targetLesson || targetLesson < 1 || targetLesson > 12) return fail(400, "BAD_LESSON", "차시를 확인해 주세요.");
        const { data: setting, error } = await db.from("sb_lesson_settings").select("locked,practice_count").eq("class_id", studentSession.classId).eq("lesson", targetLesson).maybeSingle();
      if (error || (setting?.locked ?? targetLesson !== 1)) return fail(403, "LESSON_LOCKED", "선생님이 아직 열지 않은 차시예요.");
    }

    if (action === "asset") {
      const {data:problem}=await db.from("sb_problems").select("image_path").eq("id",text(body.problemId,80)).eq("class_id",studentSession.classId).maybeSingle();
      if (!problem?.image_path?.startsWith(`${studentSession.classId}/`)) return fail(404,"ASSET_MISSING","문제 그림을 찾지 못했습니다.");
      const {data,error}=await db.storage.from("sb-problem-images").createSignedUrl(problem.image_path,300);
      return error?fail(500,"ASSET_FAILED","문제 그림을 불러오지 못했습니다."):ok({url:data.signedUrl});
    }

    if (action === "home") {
      const [classRowsRes, lessonSettingRes, progressRes, rewardRes, problemRowsRes] = await Promise.all([
        db
          .from("sb_classes")
          .select("id, name")
          .eq("id", studentSession.classId)
          .maybeSingle(),
        db.from("sb_lesson_settings").select("lesson, locked, practice_count").eq("class_id", studentSession.classId),
        db
          .from("sb_student_progress")
          .select("lesson, completed, stars")
          .eq("student_id", studentSession.studentId),
        db.from("sb_student_rewards").select("total_xp,total_stars,badges,streak").eq("student_id", studentSession.studentId).maybeSingle(),
        db
          .from("sb_problems")
          .select(
            "lesson,problem_type,title,prompt,grid_width,grid_depth,max_height,given_blocks,start_blocks,given,choices,answer,grading_mode,difficulty,xp,hint,explanation,order_index,active,id,class_id,code",
          )
          .or(`class_id.eq.${studentSession.classId},class_id.is.null`),
      ]);

      if (classRowsRes.error) return fail(500, "CLASS_ERROR", "반 정보를 읽지 못했습니다.");
      const baseClass = classRowsRes.data as ClassRow | null;
      if (!baseClass) return fail(404, "CLASS_NOT_FOUND", "반 정보를 못 찾았어요.");

      const lessonSettings = lessonSettingRes.error
        ? []
        : (lessonSettingRes.data as Array<{ lesson: number; locked: boolean; practice_count?: number | null }>) ?? [];

      if (!lessonSettingRes.error && lessonSettings.length === 0) {
        await db.from("sb_lesson_settings").upsert(makeDefaultLessonSettings(baseClass.id), {
          onConflict: "class_id,lesson",
        });
      }

      const finalLessonSettings =
        lessonSettingRes.error || lessonSettings.length === 0
          ? makeDefaultLessonSettings(baseClass.id)
          : lessonSettings;

      const progressRows = (progressRes.data as Array<{ lesson: number; completed: boolean; stars: number }>) ?? [];
      const reward = (rewardRes.data as { total_xp: number; total_stars: number; badges: unknown[]; streak: number } | null) ?? {
        total_xp: 0,
        total_stars: 0,
        badges: [],
        streak: 0,
      };

      const countByLesson = countProblemsFromRows(
        ((problemRowsRes.data as unknown[]) as DbProblemRow[])?.filter((row) => (row as DbProblemRow).active && belongsToStudentPractice(row as DbProblemRow,studentSession.studentId)) ?? [],
      );

      const [attempts, challengeXp, projectState] = await Promise.all([
        db.from("sb_problem_attempts").select("lesson,completed").eq("student_id",studentSession.studentId),
        db.from("sb_challenge_solves").select("xp").eq("student_id",studentSession.studentId),
        db.from("sb_projects").select("submitted").eq("student_id",studentSession.studentId).maybeSingle(),
      ]);
      const activityXp=(challengeXp.data??[]).reduce((sum,row)=>sum+Number(row.xp),0)+(projectState.data?.submitted?30:0);
      const lessons = Array.from({ length: 12 }, (_, index) => {
        const lesson = index + 1;
        const setting =
          finalLessonSettings.find((item) => Number(item.lesson) === lesson) ??
          { lesson, locked: lesson === 1 ? false : true };
        const progress = progressRows.find((row) => row.lesson === lesson);

        const settingCount = Number(finalLessonSettings.find((item) => Number(item.lesson) === lesson)?.practice_count);
        const totalProblems = lesson>=9 && lesson<=11 ? 1 : Math.max(countByLesson[lesson] ?? 0, [5,10,15,20].includes(settingCount) ? settingCount : recommendedPracticeCount(lesson));
        const completedProblems = progress?.completed ? totalProblems : (attempts.data??[]).filter(a=>a.lesson===lesson&&a.completed).length;
        return {
          lesson,
          locked: Boolean(setting.locked),
          totalProblems,
          completedProblems,
          stars: Number(progress?.stars ?? 0),
          completed: Boolean(progress?.completed),
        };
      });

      return ok({
        student: {
          classId: baseClass.id,
          className: baseClass.name,
          rewards: {
            totalXp: Number(reward.total_xp ?? 0)+activityXp,
            totalStars: Number(reward.total_stars ?? 0),
            badges: progressRows.filter(p=>p.completed).map(p=>`${p.lesson}차시 완료`),
            streak: Number(reward.streak ?? 0),
          },
          lessons,
        },
      });
    }

    if (action === "lessonProblems") {
      const lesson = toInt(body.lesson);
      if (!lesson) return fail(400, "BAD_LESSON", "lesson 는 1~12 사이의 값이어야 합니다.");

      let { data: problemRows } = await db
        .from("sb_problems")
        .select(
          "id,image_path, lesson, order_index, problem_type, title, prompt, grid_width, grid_depth, max_height, given_blocks, start_blocks, given, choices, answer, grading_mode, hint, explanation, difficulty, xp, active, code",
        )
        .or(`class_id.eq.${studentSession.classId},class_id.is.null`)
        .eq("lesson", lesson)
        .eq("active", true)
        .order("order_index", { ascending: true });

      const { data: lessonSetting } = await db.from("sb_lesson_settings").select("practice_count").eq("class_id", studentSession.classId).eq("lesson", lesson).maybeSingle();
      const targetCount = [5,10,15,20].includes(Number(lessonSetting?.practice_count)) ? Number(lessonSetting?.practice_count) : recommendedPracticeCount(lesson);
      const seed=practiceSeedForStudent(studentSession.studentId,lesson);
      await db.from("sb_student_progress").upsert({student_id:studentSession.studentId,lesson,practice_seed:seed},{onConflict:"student_id,lesson",ignoreDuplicates:true});
      const allRows=(problemRows as DbProblemRow[]|null)??[];
      const generatedPrefix=`GEN-L${lesson}-S${seed}-`;
      const existingRows=allRows.filter(row=>!String(row.code??'').startsWith('GEN-L')||String(row.code??'').startsWith(generatedPrefix));
      const generated=generatePracticeProblems(lesson,Math.max(0,targetCount-existingRows.length),seed);
      const existingCodes=new Set(existingRows.map(row=>row.code).filter(Boolean));
      const missing=generated.filter(item=>!existingCodes.has(item.code));
      if(missing.length){await db.from("sb_problems").insert(missing.map(generatedInsertRow));
        const refreshed=await db.from("sb_problems").select("id,image_path, lesson, order_index, problem_type, title, prompt, grid_width, grid_depth, max_height, given_blocks, start_blocks, given, choices, answer, grading_mode, hint, explanation, difficulty, xp, active, code, class_id").or(`class_id.eq.${studentSession.classId},class_id.is.null`).eq("lesson",lesson).eq("active",true).order("order_index",{ascending:true});
        problemRows=(refreshed.data?.filter(row=>!String((row as DbProblemRow).code??'').startsWith('GEN-L')||String((row as DbProblemRow).code??'').startsWith(generatedPrefix))??null) as typeof problemRows;
      }
      const parsed=(problemRows as DbProblemRow[]|null)?.map(row=>parseProblemRow(row)).filter(Boolean)??[];
      const merged = [...parsed];
      const requiredRows=(problemRows as DbProblemRow[]|null)?.filter(row=>Number(row.order_index)<=2)??[];
      const requiredIds=requiredRows.map(row=>row.id);
      const {data:requiredAttempts}=requiredIds.length?await db.from("sb_problem_attempts").select("problem_id,completed").eq("student_id",studentSession.studentId).in("problem_id",requiredIds):{data:[] as {problem_id:string;completed:boolean}[]};
      const requiredComplete=requiredIds.length>0&&requiredIds.every(id=>requiredAttempts?.some(row=>row.problem_id===id&&row.completed));
      const stages={concept:parsed.filter(p=>p?.stage==='concept').length,check:parsed.filter(p=>p?.stage==='check').length,more:parsed.filter(p=>p?.stage==='more').length};

      const problems = merged
        .filter((p) => p?.active)
        .map((problem) => sanitizeToStudentProblem(problem))
        .filter(Boolean);

      return ok({ problems, seedFallback: false, requiredComplete, stages });
    }

    if (action === "practice:new-set") {
      const lesson = toInt(body.lesson);
      if (!lesson || lesson < 1 || lesson > 12) return fail(400, "BAD_LESSON", "lesson 는 1~12 사이의 값이어야 합니다.");
      const { data: setting } = await db.from("sb_lesson_settings").select("locked").eq("class_id", studentSession.classId).eq("lesson", lesson).maybeSingle();
      if (setting?.locked ?? lesson !== 1) return fail(403, "LESSON_LOCKED", "선생님이 아직 열지 않은 차시예요.");
      const { data: current } = await db.from("sb_student_progress").select("practice_seed").eq("student_id", studentSession.studentId).eq("lesson", lesson).maybeSingle();
      const nextSeed = (Number(current?.practice_seed ?? practiceSeedForStudent(studentSession.studentId, lesson)) + 7919) % 1000000;
      const { error } = await db.from("sb_student_progress").upsert({ student_id: studentSession.studentId, lesson, practice_seed: nextSeed }, { onConflict: "student_id,lesson" });
      if (error) return fail(500, "PRACTICE_SAVE_FAILED", "새 문제 세트를 준비하지 못했습니다. 먼저 연습 설정 migration을 적용해 주세요.");
      return ok({ seed: nextSeed });
    }

    if (action === "problem") {
      const problemId = text(body.problemId, 80);
      const lesson = toInt(body.lesson);
      if (!problemId && !lesson) return fail(400, "BAD_PARAM", "문제 id 또는 lesson 가 필요합니다.");

      let row: DbProblemRow | null = null;
      if (problemId && !problemId.startsWith("seed:")) {
        const { data } = await db
          .from("sb_problems")
          .select(
            "id,image_path, lesson, order_index, problem_type, title, prompt, grid_width, grid_depth, max_height, given_blocks, start_blocks, given, choices, answer, grading_mode, hint, explanation, difficulty, xp, active, code",
          )
          .or(`class_id.eq.${studentSession.classId},class_id.is.null`)
          .eq("id", problemId)
          .maybeSingle();

        row = (data as DbProblemRow | null) ?? null;
      }

      if (!row && problemId.startsWith("seed:")) {
        const code = problemId.replace(/^seed:/, "");
        const seed = SEED_PROBLEMS.find((item) => item.code === code);
        if (!seed) return fail(404, "PROBLEM_NOT_FOUND", "문제를 찾을 수 없어요.");
        const wrapped = parseSeedProblem(seed);
        return ok({ problem: sanitizeToStudentProblem(wrapped), source: "seed" });
      }

      if (!row) return fail(404, "PROBLEM_NOT_FOUND", "문제를 찾을 수 없어요.");
      const parsed = parseProblemRow(row);
      if (!parsed) return fail(404, "PROBLEM_NOT_FOUND", "문제를 찾을 수 없어요.");

      // 시도 상태를 가져와서 힌트 공개 여부를 반영한다.
      const { data: attemptRow } = await db
        .from("sb_problem_attempts")
        .select("wrong_count, hint_shown, answer_revealed, completed")
        .eq("student_id", studentSession.studentId)
        .eq("problem_id", row.id)
        .maybeSingle();

      const problem = sanitizeToStudentProblem(parsed);
      return ok({
        problem,
        attempt: {
          wrongCount: attemptRow?.wrong_count ?? 0,
          hintShown: attemptRow?.hint_shown ?? false,
          answerRevealed: attemptRow?.answer_revealed ?? false,
          completed: attemptRow?.completed ?? false,
        },
        hint: attemptRow?.hint_shown ? String(parsed.hint ?? "") : null,
        revealedAnswer: attemptRow?.answer_revealed ? buildRevealedAnswer(parsed) : null,
      });
    }

    if (action === "attempt") {
      const problemId = text(body.problemId, 80);
      const submission = normalizeSubmission(body.submission);
      if (!problemId || !submission) return fail(400, "BAD_PARAM", "problemId 와 submission 이 필요합니다.");

      const { data: problemRow } = await db
        .from("sb_problems")
        .select(
          "id,image_path, lesson, answer, grading_mode, problem_type, prompt, title, given_blocks, start_blocks, given, choices, hint, explanation, difficulty, xp, active, grid_width, grid_depth, max_height, order_index, code",
        )
        .or(`class_id.eq.${studentSession.classId},class_id.is.null`)
        .eq("id", problemId)
        .maybeSingle();

      if (!problemRow) return fail(404, "PROBLEM_NOT_FOUND", "문제를 찾을 수 없어요.");
      const parsed = parseProblemRow(problemRow as DbProblemRow);
      if (!parsed) return fail(500, "PROBLEM_INVALID", "문제 데이터 오류");

      const { data: prevAttempt } = await db
        .from("sb_problem_attempts")
        .select("id, wrong_count, hint_shown, answer_revealed, completed, attempt_count")
        .eq("student_id", studentSession.studentId)
        .eq("problem_id", problemId)
        .maybeSingle();

      const prev = normalizeAttemptState(prevAttempt as AttemptRow | null);
      const gradeInput = {
        problemType: parsed.problemType,
        gradingMode: parsed.gradingMode,
        answer: parsed.answer,
        submission,
        given: parsed.given,
        grid: {
          gridWidth: parsed.grid.gridWidth,
          gridDepth: parsed.grid.gridDepth,
          maxHeight: parsed.grid.maxHeight,
        },
      };
      const verdict = gradeShared(gradeInput);

      const nextAttempt = applyAttempt(
        {
          wrongCount: prev.wrongCount,
          hintShown: prev.hintShown,
          answerRevealed: prev.answerRevealed,
          completed: prev.completed,
        },
        verdict.correct,
      );
      const state = nextAttempt.state;

      const { error: saveError } = await db.rpc("sb_record_attempt", {
        p_student: studentSession.studentId,
        p_problem: problemId,
        p_expected: prev.attemptCount,
        p_next: { ...state, stars: nextAttempt.stars, xp: nextAttempt.xpEarned },
        p_blocks: submission.kind === "blocks" ? canonicalize(submission.blocks) : null,
      });
      if (saveError) return fail(saveError.message.includes("ATTEMPT_CONFLICT") ? 409 : 500, "ATTEMPT_SAVE_FAILED", "시도를 저장하지 못했습니다. 진행 상태를 다시 불러온 뒤 확인해 주세요.");

      return ok({
        grade: {
          correct: verdict.correct,
          wrongCount: state.wrongCount,
          message: nextAttempt.message,
          hint: nextAttempt.sendHint ? (parsed.hint ?? "") : null,
          revealedAnswer: nextAttempt.sendAnswer
            ? {
                blocks:
                  parsed.answer.kind === "blocks"
                    ? (state.answerRevealed ? canonicalize(parsed.answer.blocks) : undefined)
                    : undefined,
                count: parsed.answer.kind === "count" ? (state.answerRevealed ? parsed.answer.value : undefined) : undefined,
                direction:
                  parsed.answer.kind === "direction"
                    ? (state.answerRevealed ? (parsed.answer.value as string | undefined) : undefined)
                    : undefined,
                choiceIndex:
                  parsed.answer.kind === "choice" && state.answerRevealed ? parsed.answer.index : undefined,
                projections:
                  parsed.answer.kind === "projections" && state.answerRevealed
                    ? safeJson(parsed.answer.projections, {})
                    : undefined,
                heightMap:
                  parsed.answer.kind === "heightMap" && state.answerRevealed
                    ? safeJson(parsed.answer.heightMap, [])
                    : undefined,
                layers:
                  parsed.answer.kind === "layers" && state.answerRevealed
                    ? safeJson(parsed.answer.layers, [])
                    : undefined,
                explanation: parsed.explanation ?? null,
              }
            : null,
          needsRebuild: nextAttempt.needsRebuild,
          completed: state.completed,
          xpEarned: nextAttempt.xpEarned,
          stars: nextAttempt.stars,
          detail: verdict.detail,
          canRetry: !nextAttempt.state.completed,
        },
      });
    }

    if (action === "snapshot" || action === "snapshot:get") {
      if (action === "snapshot") {
        const problemId = text(body.problemId, 80);
        const blocks = canonicalizeProblemBlocks((body as { blocks?: unknown }).blocks);
        const lesson = toInt(body.lesson);
        const gridWidth = toInt((body as { gridWidth?: unknown }).gridWidth) ?? 4;
        const gridDepth = toInt((body as { gridDepth?: unknown }).gridDepth) ?? 4;
        const maxHeight = toInt((body as { maxHeight?: unknown }).maxHeight) ?? 4;

        if (!problemId || !lesson) return fail(400, "BAD_PARAM", "problemId, lesson 이 필요합니다.");
        if (!problemId.startsWith("seed:")) {
          const { error } = await db.from("sb_block_snapshots").upsert(
            {
              student_id: studentSession.studentId,
              problem_id: problemId,
              lesson,
              blocks,
              grid_width: gridWidth,
              grid_depth: gridDepth,
              max_height: maxHeight,
            },
            { onConflict: "student_id,problem_id" },
          );
          if (error) return fail(500, "SAVE_FAILED", "저장하지 못했습니다. 잠시 뒤 다시 시도해 주세요.");
        }
        return ok({ ok: true, savedBlocks: blocks.length, preview: toHeightMap(blocks, { gridWidth, gridDepth, maxHeight }) });
      }

      const problemId = text(body.problemId, 80);
      if (!problemId) return fail(400, "BAD_PARAM", "problemId 가 필요합니다.");
      if (!problemId.startsWith("seed:")) {
        const { data } = await db
          .from("sb_block_snapshots")
          .select("blocks, grid_width, grid_depth, max_height")
          .eq("student_id", studentSession.studentId)
          .eq("problem_id", problemId)
          .maybeSingle();
        return ok({ snapshot: data ?? null });
      }
      return ok({ snapshot: null });
    }
  }

  // 교사용 동작
  if (action.startsWith("teacher:")) {
    const teacherId = await requireTeacher(req);
    if (!teacherId) return fail(401, "TEACHER_AUTH", "교사 인증이 필요합니다.");

    if (action === "teacher:classes") {
      const { data } = await db
        .from("sb_classes")
        .select("id, name, class_code")
        .eq("teacher_id", teacherId)
        .order("created_at", { ascending: true });
      return ok({ classes: data ?? [] });
    }

    if (action === "teacher:class-upsert") {
      try {
        const classId = text(body.classId, 80);
        const name = text(body.name, 80);
        if (!name) return fail(400, "BAD_PARAM", "반 이름이 필요합니다.");

        if (classId) {
          const has = await teacherOwnsClass(db, teacherId, classId);
          if (!has) return fail(403, "FORBIDDEN_CLASS", "해당 반에 접근할 수 없습니다.");
          await db.from("sb_classes").update({ name }).eq("id", classId);
          const { data: updated } = await db
            .from("sb_classes")
            .select("id, name, class_code")
            .eq("id", classId)
            .maybeSingle();
          return ok({ class: updated });
        }

        const requestedClassCode = text((body.classCode ?? ""), 10).toUpperCase();
        let class_code = requestedClassCode;
        let result: { error: { code?: string; message?: string } | null } = { error: null };

        // class_code 는 NOT NULL·UNIQUE 이므로 교사가 직접 입력하지 않은 경우
        // 서버에서 생성한다. 생성 코드가 우연히 충돌하면 짧게 재시도한다.
        for (let attempt = 0; attempt < 5; attempt += 1) {
          if (!class_code) class_code = generateClassCode();
          result = await db.from("sb_classes").insert({
            teacher_id: teacherId,
            name,
            class_code,
          });
          if (!result.error || result.error.code !== "23505" || requestedClassCode) break;
          class_code = "";
        }

        if (result.error) {
          if (result.error.code === "23505" && requestedClassCode) {
            return fail(409, "DUPLICATE", "이미 사용 중인 반 코드입니다.");
          }
          console.error("[student-api] teacher:class-upsert insert failed", {
            code: result.error.code ?? "UNKNOWN",
            message: result.error.message ?? "unknown database error",
          });
          return fail(500, "CLASS_CREATE_FAIL", "학급을 저장하지 못했습니다. 잠시 뒤 다시 시도해 주세요.");
        }

        const createdClass = await db
          .from("sb_classes")
          .select("id, name, class_code")
          .eq("teacher_id", teacherId)
          .eq("name", name)
          .order("created_at", { ascending: false })
          .limit(1)
          .maybeSingle();

        if (createdClass.error) {
          console.error("[student-api] teacher:class-upsert select failed", {
            code: createdClass.error.code ?? "UNKNOWN",
            message: createdClass.error.message ?? "unknown database error",
          });
          return fail(500, "CLASS_CREATE_SERVER", "학급을 저장하지 못했습니다. 잠시 뒤 다시 시도해 주세요.");
        }

        if (createdClass.data) {
          const classData = createdClass.data as ClassRow;
          const settingsResult = await db.from("sb_lesson_settings").upsert(makeDefaultLessonSettings(classData.id), {
            onConflict: "class_id,lesson",
          });
          if (settingsResult.error) {
            console.error("[student-api] teacher:class-upsert lesson defaults failed", {
              code: settingsResult.error.code ?? "UNKNOWN",
              message: settingsResult.error.message ?? "unknown database error",
            });
            return fail(500, "CLASS_CREATE_SERVER", "학급을 저장하지 못했습니다. 잠시 뒤 다시 시도해 주세요.");
          }
        }

        return ok({ class: createdClass.data });
      } catch (error) {
        console.error("[student-api] teacher:class-upsert unexpected error", error instanceof Error ? error.message : String(error));
        return fail(500, "CLASS_CREATE_SERVER", "학급을 저장하지 못했습니다. 잠시 뒤 다시 시도해 주세요.");
      }
    }

    if (action === "teacher:students:list") {
      const classId = text(body.classId, 80);
      const owns = await teacherOwnsClass(db, teacherId, classId);
      if (!owns) return fail(403, "FORBIDDEN_CLASS", "해당 반에 접근할 수 없습니다.");

      const { data: students } = await db
        .from("sb_students")
        .select("id,name,student_no,status,failed_attempts,locked_until,created_at")
        .eq("class_id", classId)
        .order("name", { ascending: true });

      const { data: vaultRows } = await db
        .from("sb_student_pin_vault")
        .select("student_id,pin_plain")
        .eq("class_id", classId);

      const pinMap = new Map((vaultRows ?? []).map((row) => [row.student_id, row.pin_plain]));
      const normalized = (students ?? []).map((row) => ({
        ...(row as Record<string, unknown>),
        pinPlain: pinMap.get((row as { id: string }).id) ?? "",
      }));
      return ok({ students: normalized });
    }

    if (action === "teacher:students:create") {
      const classId = text(body.classId, 80);
      const name = text(body.name, 40);
      const studentNo = Number.isFinite(toInt(body.studentNo)) ? toInt(body.studentNo) : null;
      if (!name) return fail(400, "BAD_PARAM", "이름이 필요합니다.");
      const owns = await teacherOwnsClass(db, teacherId, classId);
      if (!owns) return fail(403, "FORBIDDEN_CLASS", "해당 반에 접근할 수 없습니다.");

      const nextNo = studentNo;
      const pin = generatePin();
      const fakeId = crypto.randomUUID();
      const id = fakeId;
      const pinHash = await hashPin(id, pin);
      const { data: existing } = await db
        .from("sb_students")
        .select("student_no")
        .eq("class_id", classId)
        .order("student_no", { ascending: false })
        .limit(1);
      const finalNo = nextNo ?? (Number((existing?.[0] as { student_no: number } | undefined)?.student_no ?? 0) + 1);

      const inserted = await db
        .from("sb_students")
        .insert({ id, class_id: classId, name, student_no: finalNo, pin_hash: pinHash, status: "active" });

      if (inserted.error) {
        if (inserted.error.code === "23505") {
          return fail(409, "STUDENT_DUP", "동일한 이름과 번호가 이미 존재합니다.");
        }
        return fail(500, "STUDENT_CREATE_FAIL", inserted.error.message);
      }

      await db.from("sb_student_pin_vault").insert({ student_id: id, class_id: classId, pin_plain: pin });
      await db.from("sb_student_rewards").insert({ student_id: id });

      return ok({
        student: {
          id,
          name,
          studentNo: finalNo,
          status: "active",
        },
        pinPlain: pin,
      });
    }

    if (action === "teacher:students:update") {
      const studentId = text(body.studentId, 80);
      const name = text(body.name, 40);
      const status = text(body.status, 12);
      if (!studentId) return fail(400, "BAD_PARAM", "studentId 가 필요합니다.");
      const { data: student } = await db
        .from("sb_students")
        .select("class_id")
        .eq("id", studentId)
        .single();
      if (!student || !(await teacherOwnsClass(db, teacherId, student.class_id))) {
        return fail(403, "FORBIDDEN_STUDENT", "해당 학생에 접근할 수 없습니다.");
      }
      const update: Record<string, unknown> = {};
      if (name) update.name = name;
      if (status === "active" || status === "disabled") update.status = status;
      if (Object.keys(update).length === 0) return fail(400, "BAD_PARAM", "수정할 항목이 없습니다.");

      await db.from("sb_students").update(update).eq("id", studentId);
      return ok({ ok: true });
    }

    if (action === "teacher:students:pin-reset") {
      const studentId = text(body.studentId, 80);
      const pin = generatePin();
      if (!studentId) return fail(400, "BAD_PARAM", "studentId 가 필요합니다.");
      const { data: student } = await db
        .from("sb_students")
        .select("class_id")
        .eq("id", studentId)
        .maybeSingle();
      if (!student || !(await teacherOwnsClass(db, teacherId, (student as { class_id: string }).class_id))) {
        return fail(403, "FORBIDDEN_STUDENT", "해당 학생에 접근할 수 없습니다.");
      }

      const pinHash = await hashPin(studentId, pin);
      await db.from("sb_students").update({ pin_hash: pinHash }).eq("id", studentId);
      await db
        .from("sb_student_pin_vault")
        .upsert(
          {
            student_id: studentId,
            class_id: (student as { class_id: string }).class_id,
            pin_plain: pin,
          },
          { onConflict: "student_id" },
        );
      return ok({ pinPlain: pin });
    }

    if (action === "teacher:students:toggle") {
      const studentId = text(body.studentId, 80);
      const disabled = Boolean(body.disabled);
      if (!studentId) return fail(400, "BAD_PARAM", "studentId 가 필요합니다.");
      const { data: student } = await db
        .from("sb_students")
        .select("class_id")
        .eq("id", studentId)
        .maybeSingle();
      if (!student || !(await teacherOwnsClass(db, teacherId, student.class_id))) {
        return fail(403, "FORBIDDEN_STUDENT", "해당 학생에 접근할 수 없습니다.");
      }
      await db.from("sb_students").update({ status: disabled ? "disabled" : "active" }).eq("id", studentId);
      return ok({ ok: true });
    }

    if (action === "teacher:lessons:list") {
      const classId = text(body.classId, 80);
      const owns = await teacherOwnsClass(db, teacherId, classId);
      if (!owns) return fail(403, "FORBIDDEN_CLASS", "해당 반에 접근할 수 없습니다.");
      const { data } = await db
        .from("sb_lesson_settings")
        .select("lesson, locked, practice_count")
        .eq("class_id", classId)
        .order("lesson", { ascending: true });
      return ok({ lessons: (data ?? []).sort((a, b) => a.lesson - b.lesson) });
    }

    if (action === "teacher:lessons:set-lock") {
      const classId = text(body.classId, 80);
      const lesson = toInt(body.lesson);
      const locked = Boolean(body.locked);
      const practiceCount = [5,10,15,20].includes(Number(body.practiceCount)) ? Number(body.practiceCount) : undefined;
      if (!lesson) return fail(400, "BAD_PARAM", "lesson 값이 필요합니다.");
      const owns = await teacherOwnsClass(db, teacherId, classId);
      if (!owns) return fail(403, "FORBIDDEN_CLASS", "해당 반에 접근할 수 없습니다.");
      await db.from("sb_lesson_settings").upsert({ class_id: classId, lesson, locked, ...(practiceCount ? { practice_count: practiceCount } : {}) }, { onConflict: "class_id,lesson" });
      return ok({ ok: true, lesson, locked, practiceCount });
    }

    if (action === "teacher:problems:list") {
      const classId = text(body.classId, 80);
      const owns = await teacherOwnsClass(db, teacherId, classId);
      if (!owns) return fail(403, "FORBIDDEN_CLASS", "해당 반에 접근할 수 없습니다.");

      const { data: classProblems } = await db
        .from("sb_problems")
        .select(
          "id,image_path, lesson, order_index, problem_type, title, prompt, grid_width, grid_depth, max_height, given_blocks, start_blocks, given, choices, grading_mode, answer, hint, explanation, difficulty, xp, active, code",
        )
        .eq("class_id", classId)
        .order("lesson", { ascending: true })
        .order("order_index", { ascending: true });

      const custom = (classProblems ?? []).map((row) => parseProblemRow(row as DbProblemRow)).filter(Boolean);
      const seed = SEED_PROBLEMS.map((seed) => parseSeedProblem(seed));

      return ok({
        customProblems: custom.map((row) => sanitizeToStudentProblem(row)).filter(Boolean),
        builtinCount: seed.length,
      });
    }

    if (action === "teacher:problems:set-active") {
      const problemId = text(body.problemId, 80);
      const active = Boolean(body.active);
      if (!problemId || problemId.startsWith("seed:")) {
        return fail(400, "BAD_PARAM", "커스텀 문제 id 만 변경할 수 있습니다.");
      }
      const { data: target } = await db.from("sb_problems").select("class_id").eq("id", problemId).maybeSingle();
      if (!target?.class_id || !(await teacherOwnsClass(db, teacherId, target.class_id))) {
        return fail(403, "FORBIDDEN_CLASS", "해당 반에 접근할 수 없습니다.");
      }
      const { error } = await db.from("sb_problems").update({ active }).eq("id", problemId);
      if (error) return fail(500, "SAVE_FAILED", "문제 상태를 저장하지 못했습니다.");
      return ok({ ok: true, active });
    }

    return fail(400, "BAD_ACTION", "지원되지 않는 teacher action 입니다.");
  }

  return fail(400, "BAD_ACTION", "지원되지 않는 action 입니다.");
});

import { ACTIVITY_GRID, challengeGiven, challengeScore, validBuilding, validChallenge, type Building, type ChallengeType } from '../../../shared/activities.ts';
import { canonicalize, validStructure } from '../../../shared/blocks.ts';
import { grade } from '../../../shared/grading.ts';
import { applyAttempt } from '../../../shared/attempts.ts';
import type { BlockCoord } from '../../../shared/types.ts';
import { generateShareCode } from './security.ts';
import { fail,ok,text } from './http.ts';
import type { serviceClient } from './db.ts';
export async function activityRequest(db:ReturnType<typeof serviceClient>, body:Record<string,unknown>, student:{studentId:string;classId:string}) {
 const action=String(body.action);
 const lesson=action.includes('challenge')?9:action.includes('review')?12:body.lesson===11?11:10;
 const {data:lock,error:lockError}=await db.from('sb_lesson_settings').select('locked').eq('class_id',student.classId).eq('lesson',lesson).maybeSingle();
 if(lockError||lock?.locked!==false)return fail(403,'LESSON_LOCKED','선생님이 아직 열지 않은 차시예요.');
 if(action==='activity:project:get'){
  const {data,error}=await db.from('sb_projects').select('building_name,reason,description,layer_notes,blocks,version,submitted').eq('student_id',student.studentId).eq('class_id',student.classId).maybeSingle();
  return error?fail(500,'LOAD_FAILED','설계를 불러오지 못했습니다.'):ok({building:data});
 }
 if(action==='activity:project:save'){
  const building=body.building as Building;
  if(building?.submitted&&lesson!==11)return fail(400,'SUBMIT_ON_LESSON_11','소개서 완성은 11차시에서 할 수 있습니다.');
  if(!building||!validBuilding(building,building.submitted)||!Number.isInteger(building.version))return fail(400,'INVALID_BUILDING','건축물 이름, 설계 이유, 3개 층의 설명과 3층 모양을 확인해 주세요.');
  const {data,error}=await db.rpc('sb_save_building',{p_student:student.studentId,p_class:student.classId,p_version:building.version,p_data:{...building,blocks:canonicalize(building.blocks)}});
  return error?fail(error.message.includes('VERSION_CONFLICT')?409:500,'SAVE_CONFLICT','다른 창에서 수정했거나 저장에 실패했습니다. 기기 기록을 보관했습니다. 서버 상태를 다시 확인해 주세요.'):ok({version:data});
 }
 if(action==='activity:challenge:create'){
  const blocks=body.blocks as BlockCoord[],type=String(body.type);
  if(!validChallenge(blocks,type))return fail(400,'TEN_BLOCKS','쌓기나무를 정확히 10개 사용해 주세요.');
  const code=generateShareCode();
  const {error}=await db.from('sb_shared_challenges').insert({class_id:student.classId,author_id:student.studentId,share_code:code,challenge_type:type,blocks:canonicalize(blocks),grid_width:5,grid_depth:5,max_height:3});
  return error?fail(500,'SAVE_FAILED','문제 저장에 실패했습니다. 다시 시도해 주세요.'):ok({code});
 }
 if(action==='activity:challenge:get'||action==='activity:challenge:hint'||action==='activity:challenge:attempt'){
  const {data:c,error}=await db.from('sb_shared_challenges').select('*').eq('share_code',text(body.code,12).toUpperCase()).eq('class_id',student.classId).maybeSingle();
  if(error||!c)return fail(404,'NOT_FOUND','우리 반 문제 코드를 확인해 주세요.');
  const {data:prior}=await db.from('sb_challenge_solves').select('*').eq('challenge_id',c.id).eq('student_id',student.studentId).maybeSingle();
  const state={wrongCount:prior?.wrong_count??0,hintShown:prior?.used_hint??false,answerRevealed:prior?.answer_revealed??false,completed:prior?.correct??false,score:prior?.score??0};
  const given=challengeGiven(c.blocks,c.challenge_type as ChallengeType);
  if(action==='activity:challenge:get')return ok({given,state,answer:state.answerRevealed?c.blocks:null});
  if(action==='activity:challenge:hint'){
   if(state.completed)return ok({state,hint:'이미 완료한 문제예요.'});
   const hinted={...state,hintShown:true};
   const {error:hintError}=await db.rpc('sb_submit_challenge',{p_student:student.studentId,p_challenge:c.id,p_previous:state.wrongCount,p_state:{...hinted,xp:0,score:0}});
   if(hintError)return fail(409,'SAVE_FAILED','힌트를 저장하지 못했습니다. 다시 시도해 주세요.');
   return ok({state:hinted,hint:'각 자리의 높이와 보이지 않는 블록을 차례로 살펴보세요.'});
  }
  const blocks=body.blocks as BlockCoord[];
  if(!validStructure(blocks,ACTIVITY_GRID))return fail(400,'INVALID_BLOCKS','블록 위치를 확인해 주세요.');
  const correct=grade({problemType:'BUILD_FROM_VIEWS',gradingMode:c.challenge_type==='views'?'constraint':'exact',answer:{kind:'blocks',blocks:c.blocks},submission:{kind:'blocks',blocks},given,grid:ACTIVITY_GRID}).correct&&blocks.length===10;
  const outcome=applyAttempt(state,correct);
  const score=challengeScore(outcome.state.hintShown,outcome.state.answerRevealed,outcome.state.completed);
  const {error:saveError}=await db.rpc('sb_submit_challenge',{p_student:student.studentId,p_challenge:c.id,p_previous:state.wrongCount,p_state:{...outcome.state,xp:outcome.xpEarned,score}});
  if(saveError)return fail(409,'SAVE_FAILED','시도를 저장하지 못했습니다. 문제를 다시 열어 주세요.');
  return ok({outcome,state:{...outcome.state,score},answer:outcome.state.answerRevealed?c.blocks:null,hint:outcome.state.hintShown?'각 자리의 높이와 보이지 않는 블록을 차례로 살펴보세요.':null,score});
 }
 if(action==='activity:review:save'){
  const confidence=Number(body.confidence);
  if(![1,2,3].includes(confidence))return fail(400,'BAD_VALUE','자기평가를 선택해 주세요.');
  const {error}=await db.from('sb_self_evaluations').upsert({student_id:student.studentId,confidence,reflection:text(body.reflection,1000)});
  return error?fail(500,'SAVE_FAILED','저장하지 못했습니다.'):ok({saved:true});
 }
 return fail(400,'BAD_ACTION','지원하지 않는 활동입니다.');
}

import { canonicalize, project, toHeightMap, toLayers, validStructure } from './blocks.ts';
import type { BlockCoord } from './types.ts';
export const ACTIVITY_GRID = {gridWidth:5,gridDepth:5,maxHeight:3};
export type ChallengeType = 'views'|'heightMap'|'layers';
export interface Building { building_name:string;reason:string;description:string;layer_notes:string[];blocks:BlockCoord[];version:number;submitted:boolean }
export const EMPTY_BUILDING:Building={building_name:'',reason:'',description:'',layer_notes:['','',''],blocks:[],version:0,submitted:false};
export function validBuilding(value:Building,complete=false) {
  if (!value || !Array.isArray(value.layer_notes)) return false;
  return validStructure(value.blocks,ACTIVITY_GRID) && [value.building_name,value.reason,value.description,...value.layer_notes].every(s=>typeof s==='string'&&s.length<=2000)
    && value.layer_notes.length===3 && (!complete || (value.building_name.trim().length>0 && value.reason.trim().length>0 && value.description.trim().length>0 && value.layer_notes.every(s=>s.trim()) && value.blocks.some(b=>b.y===2)));
}
export function challengeGiven(blocks:BlockCoord[],type:ChallengeType) {
  return type==='heightMap'?{heightMap:toHeightMap(blocks,ACTIVITY_GRID)}:type==='layers'?{layers:toLayers(blocks,ACTIVITY_GRID)}:{projections:project(blocks,ACTIVITY_GRID)};
}
export function validChallenge(blocks:BlockCoord[],type:string) { return ['views','heightMap','layers'].includes(type)&&validStructure(blocks,ACTIVITY_GRID)&&canonicalize(blocks).length===10; }
export function challengeScore(hintShown:boolean, answerRevealed:boolean, completed:boolean):number {
  if (!completed || answerRevealed) return 0;
  return hintShown ? 1 : 2;
}

import type { BlockCoord, Grid2D, GridConfig, HeightMap, Projections } from "./types.ts";

/**
 * 쌓기나무 좌표를 다루는 핵심 모듈.
 *
 * 여기서 정한 규칙을 학생 화면, 교사 제작기, 채점이 모두 똑같이 쓴다.
 * 화면 픽셀을 비교하는 곳은 어디에도 없다 (명세 16).
 */

export function keyOf(c: BlockCoord): string {
  return `${c.x},${c.y},${c.z}`;
}

/**
 * 저장·비교 전에 항상 같은 규칙으로 정렬한다 (명세 7).
 * 중복 좌표도 함께 걸러낸다.
 */
export function canonicalize(blocks: BlockCoord[]): BlockCoord[] {
  const seen = new Set<string>();
  const unique: BlockCoord[] = [];

  for (const b of blocks) {
    const c = { x: Math.trunc(b.x), y: Math.trunc(b.y), z: Math.trunc(b.z) };
    const key = keyOf(c);
    if (seen.has(key)) continue;
    seen.add(key);
    unique.push(c);
  }

  return unique.sort((a, b) => a.y - b.y || a.z - b.z || a.x - b.x);
}

export function blocksEqual(a: BlockCoord[], b: BlockCoord[]): boolean {
  const ca = canonicalize(a);
  const cb = canonicalize(b);
  if (ca.length !== cb.length) return false;
  for (let i = 0; i < ca.length; i++) {
    if (ca[i].x !== cb[i].x || ca[i].y !== cb[i].y || ca[i].z !== cb[i].z) return false;
  }
  return true;
}

export function hasBlockAt(blocks: BlockCoord[], x: number, y: number, z: number): boolean {
  return blocks.some((b) => b.x === x && b.y === y && b.z === z);
}

export function inBounds(c: BlockCoord, grid: GridConfig): boolean {
  return (
    Number.isInteger(c.x) && Number.isInteger(c.y) && Number.isInteger(c.z) &&
    c.x >= 0 &&
    c.x < grid.gridWidth &&
    c.z >= 0 &&
    c.z < grid.gridDepth &&
    c.y >= 0 &&
    c.y < grid.maxHeight
  );
}

/** (x,z) 자리에 쌓인 높이. 곧 그 자리에 새로 놓을 y 값이기도 하다. */
export function columnHeight(blocks: BlockCoord[], x: number, z: number): number {
  let height = 0;
  for (const b of blocks) {
    if (b.x === x && b.z === z && b.y + 1 > height) height = b.y + 1;
  }
  return height;
}

// ---------------------------------------------------------------------------
// 물리 규칙 (명세 11)
// ---------------------------------------------------------------------------

export type PlaceRejection = "out_of_bounds" | "occupied" | "floating" | "too_high";

export interface PlaceCheck {
  ok: boolean;
  reason?: PlaceRejection;
  message?: string;
}

const REJECTION_MESSAGES: Record<PlaceRejection, string> = {
  out_of_bounds: "작업판 밖에는 놓을 수 없어요.",
  occupied: "그 자리에는 이미 쌓기나무가 있어요.",
  floating: "쌓기나무는 공중에 뜰 수 없어요. 아래를 먼저 채워 주세요.",
  too_high: "더 높이 쌓을 수 없어요.",
};

/** 공중에 뜬 블록을 막는다. y>0 이면 바로 아래 칸에 블록이 있어야 한다. */
export function canPlace(blocks: BlockCoord[], target: BlockCoord, grid: GridConfig): PlaceCheck {
  if (target.y >= grid.maxHeight) {
    return { ok: false, reason: "too_high", message: REJECTION_MESSAGES.too_high };
  }
  if (!inBounds(target, grid)) {
    return { ok: false, reason: "out_of_bounds", message: REJECTION_MESSAGES.out_of_bounds };
  }
  if (hasBlockAt(blocks, target.x, target.y, target.z)) {
    return { ok: false, reason: "occupied", message: REJECTION_MESSAGES.occupied };
  }
  if (target.y > 0 && !hasBlockAt(blocks, target.x, target.y - 1, target.z)) {
    return { ok: false, reason: "floating", message: REJECTION_MESSAGES.floating };
  }
  return { ok: true };
}

/** (x,z) 기둥 맨 위에 한 칸 올린다. 드래그해서 놓을 때 쓰는 기본 동작. */
export function placeOnColumn(
  blocks: BlockCoord[],
  x: number,
  z: number,
  grid: GridConfig,
): { blocks: BlockCoord[]; check: PlaceCheck } {
  const target = { x, y: columnHeight(blocks, x, z), z };
  const check = canPlace(blocks, target, grid);
  if (!check.ok) return { blocks, check };
  return { blocks: canonicalize([...blocks, target]), check };
}

/**
 * 삭제 정책 A (명세 11): 위에 블록이 있으면 아래 블록은 지울 수 없다.
 * 교육용으로는 이 쪽이 안전하다 - 지웠더니 위 블록이 내려앉는 혼란이 없다.
 */
export function canRemove(blocks: BlockCoord[], target: BlockCoord): PlaceCheck {
  if (!hasBlockAt(blocks, target.x, target.y, target.z)) {
    return { ok: false, message: "그 자리에는 쌓기나무가 없어요." };
  }
  if (hasBlockAt(blocks, target.x, target.y + 1, target.z)) {
    return {
      ok: false,
      message: "위에 쌓기나무가 있어서 먼저 위쪽 블록을 옮겨야 해요.",
    };
  }
  return { ok: true };
}

export function removeBlock(
  blocks: BlockCoord[],
  target: BlockCoord,
): { blocks: BlockCoord[]; check: PlaceCheck } {
  const check = canRemove(blocks, target);
  if (!check.ok) return { blocks, check };
  return {
    blocks: blocks.filter((b) => !(b.x === target.x && b.y === target.y && b.z === target.z)),
    check,
  };
}

/** 기둥 맨 위 한 칸을 뺀다. 터치 환경에서 누르기 쉬운 삭제 방식. */
export function removeTopOfColumn(
  blocks: BlockCoord[],
  x: number,
  z: number,
): { blocks: BlockCoord[]; check: PlaceCheck } {
  const height = columnHeight(blocks, x, z);
  if (height === 0) return { blocks, check: { ok: false, message: "그 자리에는 쌓기나무가 없어요." } };
  return removeBlock(blocks, { x, y: height - 1, z });
}

/** 블록 하나를 다른 기둥으로 옮긴다. 옮길 수 없으면 원래대로 둔다. */
export function moveBlock(
  blocks: BlockCoord[],
  from: BlockCoord,
  toX: number,
  toZ: number,
  grid: GridConfig,
): { blocks: BlockCoord[]; check: PlaceCheck } {
  const removal = removeBlock(blocks, from);
  if (!removal.check.ok) return { blocks, check: removal.check };

  const placement = placeOnColumn(removal.blocks, toX, toZ, grid);
  if (!placement.check.ok) return { blocks, check: placement.check };

  return { blocks: placement.blocks, check: { ok: true } };
}

// ---------------------------------------------------------------------------
// 표현 변환
// ---------------------------------------------------------------------------

export function countBlocks(blocks: BlockCoord[]): number {
  return canonicalize(blocks).length;
}

export function emptyGrid2D(rows: number, cols: number): Grid2D {
  return Array.from({ length: rows }, () => Array<boolean>(cols).fill(false));
}

export function emptyHeightMap(grid: GridConfig): HeightMap {
  return Array.from({ length: grid.gridDepth }, () => Array<number>(grid.gridWidth).fill(0));
}

export function toHeightMap(blocks: BlockCoord[], grid: GridConfig): HeightMap {
  const map = emptyHeightMap(grid);
  for (const b of blocks) {
    if (b.x < 0 || b.x >= grid.gridWidth || b.z < 0 || b.z >= grid.gridDepth) continue;
    map[b.z][b.x] = Math.max(map[b.z][b.x], Math.min(b.y + 1, grid.maxHeight));
  }
  return map;
}

export function fromHeightMap(map: HeightMap): BlockCoord[] {
  const blocks: BlockCoord[] = [];
  for (let z = 0; z < map.length; z++) {
    for (let x = 0; x < map[z].length; x++) {
      for (let y = 0; y < map[z][x]; y++) blocks.push({ x, y, z });
    }
  }
  return canonicalize(blocks);
}

/** 공중에 뜬 블록을 아래로 내려 항상 유효한 모양으로 만든다. */
export function settle(blocks: BlockCoord[], grid: GridConfig): BlockCoord[] {
  return fromHeightMap(toHeightMap(blocks, grid));
}

/**
 * 위·앞·옆에서 본 모양을 계산한다 (명세 24).
 *
 * 화면에 보이는 그대로의 순서로 만든다. 즉 격자를 그대로 출력하면
 * 3D 화면에서 해당 시점 버튼을 눌렀을 때와 좌우가 일치한다.
 *   위  : 카메라 +y, 화면 오른쪽 = +x, 화면 아래 = +z  → top[z][x]
 *   앞  : 카메라 -z, 화면 오른쪽 = +x, 화면 위 = +y    → front[y][x]
 *   옆  : 카메라 +x(오른쪽 옆), 화면 오른쪽 = -z       → side[y][depth-1-z]
 */
export function project(blocks: BlockCoord[], grid: GridConfig): Projections {
  const top = emptyGrid2D(grid.gridDepth, grid.gridWidth);
  const front = emptyGrid2D(grid.maxHeight, grid.gridWidth);
  const side = emptyGrid2D(grid.maxHeight, grid.gridDepth);

  for (const b of blocks) {
    if (b.z >= 0 && b.z < grid.gridDepth && b.x >= 0 && b.x < grid.gridWidth) top[b.z][b.x] = true;
    if (b.y >= 0 && b.y < grid.maxHeight) {
      if (b.x >= 0 && b.x < grid.gridWidth) front[b.y][b.x] = true;
      if (b.z >= 0 && b.z < grid.gridDepth) side[b.y][grid.gridDepth - 1 - b.z] = true;
    }
  }

  return { top, front, side };
}

/** 층별 격자 (명세 29). layers[0] 이 1층. */
export function toLayers(blocks: BlockCoord[], grid: GridConfig): Grid2D[] {
  const layers: Grid2D[] = Array.from({ length: grid.maxHeight }, () =>
    emptyGrid2D(grid.gridDepth, grid.gridWidth),
  );
  for (const b of blocks) {
    if (b.y < 0 || b.y >= grid.maxHeight) continue;
    if (b.z < 0 || b.z >= grid.gridDepth) continue;
    if (b.x < 0 || b.x >= grid.gridWidth) continue;
    layers[b.y][b.z][b.x] = true;
  }
  return layers;
}

export function fromLayers(layers: Grid2D[]): BlockCoord[] {
  const blocks: BlockCoord[] = [];
  layers.forEach((layer, y) => {
    layer.forEach((row, z) => {
      row.forEach((filled, x) => {
        if (filled) blocks.push({ x, y, z });
      });
    });
  });
  return canonicalize(blocks);
}

export function grid2DEqual(a: Grid2D | undefined, b: Grid2D | undefined): boolean {
  if (!a || !b) return false;
  if (a.length !== b.length) return false;
  for (let i = 0; i < a.length; i++) {
    if (a[i].length !== b[i].length) return false;
    for (let j = 0; j < a[i].length; j++) {
      if (a[i][j] !== b[i][j]) return false;
    }
  }
  return true;
}

export function heightMapEqual(a: HeightMap | undefined, b: HeightMap | undefined): boolean {
  if (!a || !b) return false;
  if (a.length !== b.length) return false;
  for (let z = 0; z < a.length; z++) {
    if (a[z].length !== b[z].length) return false;
    for (let x = 0; x < a[z].length; x++) {
      if (a[z][x] !== b[z][x]) return false;
    }
  }
  return true;
}

/** 몇 층까지 쌓였는지. 층별 보기 컨트롤의 최대값으로 쓴다. */
export function usedHeight(blocks: BlockCoord[]): number {
  return blocks.reduce((max, b) => Math.max(max, b.y + 1), 0);
}

/** 층별 개수. 4차시 '층별로 나누어 세기' 전략에 쓴다. */
export function countByLayer(blocks: BlockCoord[], grid: GridConfig): number[] {
  const counts = Array<number>(grid.maxHeight).fill(0);
  for (const b of blocks) {
    if (b.y >= 0 && b.y < grid.maxHeight) counts[b.y]++;
  }
  return counts;
}

/** Reject malformed input before canonicalization; never repair a submitted answer. */
export function validStructure(blocks: BlockCoord[], grid: GridConfig): boolean {
  if (!Array.isArray(blocks) || blocks.length > grid.gridWidth * grid.gridDepth * grid.maxHeight) return false;
  const seen = new Set<string>();
  for (const block of blocks) {
    if (!block || !inBounds(block, grid) || seen.has(keyOf(block))) return false;
    seen.add(keyOf(block));
  }
  return blocks.every(block => block.y === 0 || seen.has(keyOf({ ...block, y: block.y - 1 })));
}

import {
  blocksEqual,
  canonicalize,
  countBlocks,
  grid2DEqual,
  heightMapEqual,
  project,
  validStructure,
} from "./blocks.ts";
import type {
  GradingMode,
  GridConfig,
  ProblemAnswer,
  ProblemGiven,
  ProblemType,
  Projections,
  StudentSubmission,
} from "./types.ts";

/**
 * 자동채점 (명세 16).
 *
 * 절대 렌더링 화면 픽셀을 비교하지 않는다. 항상 좌표·격자 데이터를 비교한다.
 * 이 파일은 브라우저와 Edge Function 이 똑같이 쓴다.
 */

export interface GradeInput {
  problemType: ProblemType;
  gradingMode: GradingMode;
  answer: ProblemAnswer;
  submission: StudentSubmission;
  given: ProblemGiven;
  grid: GridConfig;
}

export interface GradeVerdict {
  correct: boolean;
  /** 왜 틀렸는지에 대한 짧은 단서. 정답 자체는 담지 않는다. */
  detail: string | null;
}

/** 학생이 쌓은 모양이 주어진 세 방향 조건을 모두 만족하는지 (명세 27 constraint). */
function satisfiesProjections(
  studentBlocks: { x: number; y: number; z: number }[],
  required: Partial<Projections>,
  grid: GridConfig,
): GradeVerdict {
  const actual = project(studentBlocks, grid);

  if (required.top && !grid2DEqual(actual.top, required.top)) {
    return { correct: false, detail: "위에서 본 모양이 조건과 달라요." };
  }
  if (required.front && !grid2DEqual(actual.front, required.front)) {
    return { correct: false, detail: "앞에서 본 모양이 조건과 달라요." };
  }
  if (required.side && !grid2DEqual(actual.side, required.side)) {
    return { correct: false, detail: "옆에서 본 모양이 조건과 달라요." };
  }
  return { correct: true, detail: null };
}

export function grade(input: GradeInput): GradeVerdict {
  const { answer, submission, gradingMode, given, grid, problemType } = input;

  const expectedKinds: Record<ProblemType, StudentSubmission["kind"]> = {
    FREE_BUILD: "blocks", BLOCK_POSITION: "choice", CAMERA_DIRECTION: "direction", PROJECTION_DRAW: "projections",
    COUNT: "count", COUNT_AMBIGUOUS: "count", BUILD_FROM_VIEWS: "blocks", BUILD_FROM_HEIGHTMAP: "blocks",
    HEIGHTMAP_FROM_BUILD: "heightMap", BUILD_FROM_LAYERS: "blocks", LAYER_DRAW: "layers", PATTERN_NEXT: "count", CHOICE: "choice",
  };
  if (submission.kind !== expectedKinds[problemType]) return { correct: false, detail: "문제에 맞는 방식으로 답해 주세요." };

  if (submission.kind === "blocks" && !validStructure(submission.blocks, grid)) {
    return { correct: false, detail: "작업판 안에서 아래부터 차례로 쌓아 주세요." };
  }

  // 자유 쌓기는 정해진 정답이 없다. 최소 개수만 채우면 완료로 본다.
  if (problemType === "FREE_BUILD") {
    if (submission.kind !== "blocks") return { correct: false, detail: null };
    const placed = countBlocks(submission.blocks);
    const need = given.minBlocks ?? 1;
    return placed >= need
      ? { correct: true, detail: null }
      : { correct: false, detail: `쌓기나무를 ${need}개 이상 쌓아 보세요. (지금 ${placed}개)` };
  }

  // --- 블록 쌓기 문제 ---
  if (submission.kind === "blocks") {
    const settled = canonicalize(submission.blocks);

    if (settled.length === 0) {
      return { correct: false, detail: "아직 쌓기나무를 놓지 않았어요." };
    }

    // 조건 만족형: 여러 모양이 모두 정답일 수 있다 (명세 27).
    if (gradingMode === "constraint") {
      const required = given.projections ?? (answer.kind === "projections" ? answer.projections : null);
      if (required) return satisfiesProjections(settled, required, grid);
      if (answer.kind === "heightMap") {
        return heightMapEqual(
          require_heightMap(settled, grid),
          answer.heightMap,
        )
          ? { correct: true, detail: null }
          : { correct: false, detail: "각 자리의 층수가 조건과 달라요." };
      }
    }

    if (answer.kind !== "blocks") {
      return { correct: false, detail: "이 문제는 쌓아서 답하는 문제가 아니에요." };
    }

    if (blocksEqual(settled, answer.blocks)) return { correct: true, detail: null };

    const mine = countBlocks(settled);
    const theirs = countBlocks(answer.blocks);
    if (mine !== theirs) {
      return {
        correct: false,
        detail: `쌓기나무 개수가 달라요. (내가 쌓은 개수: ${mine}개)`,
      };
    }
    return { correct: false, detail: "개수는 맞지만 놓인 자리가 달라요." };
  }

  // --- 개수 문제 ---
  if (submission.kind === "count") {
    if (answer.kind === "count") {
      return submission.value === answer.value
        ? { correct: true, detail: null }
        : { correct: false, detail: "개수를 다시 세어 볼까요?" };
    }
    if (answer.kind === "blocks") {
      return submission.value === countBlocks(answer.blocks)
        ? { correct: true, detail: null }
        : { correct: false, detail: "개수를 다시 세어 볼까요?" };
    }
    return { correct: false, detail: null };
  }

  // --- 방향 문제 ---
  if (submission.kind === "direction") {
    return answer.kind === "direction" && submission.value === answer.value
      ? { correct: true, detail: null }
      : { correct: false, detail: "다른 방향에서 본 모습과 견주어 보세요." };
  }

  // --- 보기 고르기 ---
  if (submission.kind === "choice") {
    return answer.kind === "choice" && submission.index === answer.index
      ? { correct: true, detail: null }
      : { correct: false, detail: null };
  }

  // --- 위/앞/옆 격자 그리기 ---
  if (submission.kind === "projections") {
    if (answer.kind !== "projections") return { correct: false, detail: null };
    const wanted = answer.projections;
    const mine = submission.projections;

    for (const face of ["top", "front", "side"] as const) {
      if (!wanted[face]) continue;
      if (!grid2DEqual(mine[face], wanted[face])) {
        const label = face === "top" ? "위" : face === "front" ? "앞" : "옆";
        return { correct: false, detail: `${label}에서 본 모양을 다시 살펴보세요.` };
      }
    }
    return { correct: true, detail: null };
  }

  // --- 위에서 본 모양에 수 쓰기 ---
  if (submission.kind === "heightMap") {
    const wanted =
      answer.kind === "heightMap"
        ? answer.heightMap
        : answer.kind === "blocks"
          ? require_heightMap(answer.blocks, grid)
          : null;
    if (!wanted) return { correct: false, detail: null };

    return heightMapEqual(submission.heightMap, wanted)
      ? { correct: true, detail: null }
      : { correct: false, detail: "숫자가 다른 자리가 있어요." };
  }

  // --- 층별 격자 ---
  if (submission.kind === "layers") {
    const wanted = answer.kind === "layers" ? answer.layers : null;
    if (!wanted) return { correct: false, detail: null };
    if (submission.layers.length !== wanted.length) {
      return { correct: false, detail: "층 수가 달라요." };
    }
    for (let i = 0; i < wanted.length; i++) {
      if (!grid2DEqual(submission.layers[i], wanted[i])) {
        return { correct: false, detail: `${i + 1}층 모양을 다시 살펴보세요.` };
      }
    }
    return { correct: true, detail: null };
  }

  return { correct: false, detail: null };
}

/** blocks.ts 의 toHeightMap 을 쓰되 canonicalize 를 먼저 태운다. */
function require_heightMap(
  blocks: { x: number; y: number; z: number }[],
  grid: GridConfig,
): number[][] {
  const map: number[][] = Array.from({ length: grid.gridDepth }, () =>
    Array<number>(grid.gridWidth).fill(0),
  );
  for (const b of canonicalize(blocks)) {
    if (b.x < 0 || b.x >= grid.gridWidth || b.z < 0 || b.z >= grid.gridDepth) continue;
    map[b.z][b.x] = Math.max(map[b.z][b.x], Math.min(b.y + 1, grid.maxHeight));
  }
  return map;
}

/**
 * 오답 처리 규칙 (명세 17) - 이 앱에서 가장 중요한 규칙.
 *
 *   1회 오답            → "다시 살펴보세요."      (힌트 X, 정답 X)
 *   2회 오답            → "조금만 더 생각해 볼까요?" (힌트 X, 정답 X)
 *   3회 오답            → 힌트 제공                (정답 X)
 *   힌트를 본 뒤 또 오답 → 그때 정답 공개
 *
 * 3번 틀렸다고 바로 정답을 보여 주지 않는다.
 * 정답을 본 뒤에는 스스로 다시 쌓아야 완료된다 (명세 18).
 */

export interface AttemptState {
  /** 지금까지 틀린 횟수. */
  wrongCount: number;
  /** 힌트를 이미 봤는지. */
  hintShown: boolean;
  /** 정답을 이미 공개했는지. */
  answerRevealed: boolean;
  /** 완료 처리되었는지. */
  completed: boolean;
}

export const INITIAL_ATTEMPT: AttemptState = {
  wrongCount: 0,
  hintShown: false,
  answerRevealed: false,
  completed: false,
};

/** 게임 보상 (명세 19). 학업 평가 점수와는 연결하지 않는다. */
export const XP_REWARD = {
  /** 힌트 없이 해결 */
  withoutHint: 30,
  /** 힌트 후 해결 */
  afterHint: 20,
  /** 정답을 본 뒤 다시 완성 */
  afterReveal: 10,
} as const;

export const STAR_REWARD = {
  withoutHint: 3,
  afterHint: 2,
  afterReveal: 1,
} as const;

export type AttemptAction =
  | "none"
  | "retry"
  | "show_hint"
  | "reveal_answer"
  | "rebuild_required"
  | "complete";

export interface AttemptOutcome {
  state: AttemptState;
  action: AttemptAction;
  message: string;
  /** 이번 응답에서 힌트를 함께 내려보내야 하는지. */
  sendHint: boolean;
  /** 이번 응답에서 정답을 함께 내려보내야 하는지. */
  sendAnswer: boolean;
  /** 정답을 보고 다시 쌓아야 완료되는 상태인지. */
  needsRebuild: boolean;
  xpEarned: number;
  stars: number;
}

const WRONG_MESSAGES = [
  "다시 살펴보세요.",
  "조금만 더 생각해 볼까요?",
] as const;

/**
 * 한 번의 제출 결과를 상태 기계에 통과시킨다.
 * 서버(Edge Function)에서 호출해 그 결과만 학생에게 내려보낸다.
 */
export function applyAttempt(prev: AttemptState, correct: boolean): AttemptOutcome {
  // 이미 완료한 문제를 다시 풀어도 보상은 중복 지급하지 않는다.
  if (prev.completed) {
    return {
      state: prev,
      action: "none",
      message: correct ? "이미 완료한 문제예요." : "이미 완료한 문제예요.",
      sendHint: false,
      sendAnswer: false,
      needsRebuild: false,
      xpEarned: 0,
      stars: 0,
    };
  }

  if (correct) {
    const xpEarned = prev.answerRevealed
      ? XP_REWARD.afterReveal
      : prev.hintShown
        ? XP_REWARD.afterHint
        : XP_REWARD.withoutHint;

    const stars = prev.answerRevealed
      ? STAR_REWARD.afterReveal
      : prev.hintShown
        ? STAR_REWARD.afterHint
        : STAR_REWARD.withoutHint;

    const message = prev.answerRevealed
      ? "정답 모양대로 다시 잘 쌓았어요. 완료!"
      : prev.hintShown
        ? "힌트를 잘 활용했어요. 정답이에요!"
        : "정답이에요! 한 번에 해냈네요.";

    return {
      state: { ...prev, completed: true },
      action: "complete",
      message,
      sendHint: false,
      sendAnswer: false,
      needsRebuild: false,
      xpEarned,
      stars,
    };
  }

  const wrongCount = prev.wrongCount + 1;

  // 정답을 이미 본 상태 - 스스로 다시 쌓을 때까지 기다린다.
  if (prev.answerRevealed) {
    return {
      state: { ...prev, wrongCount },
      action: "rebuild_required",
      message: "정답 모양을 한 번 더 살펴보고, 똑같이 다시 쌓아 보세요.",
      sendHint: false,
      sendAnswer: true,
      needsRebuild: true,
      xpEarned: 0,
      stars: 0,
    };
  }

  // 힌트를 본 뒤에도 틀렸다 - 이제 정답을 공개한다.
  if (prev.hintShown) {
    return {
      state: { ...prev, wrongCount, answerRevealed: true },
      action: "reveal_answer",
      message: "정답 모양을 보여 줄게요. 잘 살펴보고 똑같이 다시 쌓아 보세요.",
      sendHint: true,
      sendAnswer: true,
      needsRebuild: true,
      xpEarned: 0,
      stars: 0,
    };
  }

  // 3회째 오답 - 힌트를 준다. 정답은 아직 보여 주지 않는다.
  if (wrongCount >= 3) {
    return {
      state: { ...prev, wrongCount, hintShown: true },
      action: "show_hint",
      message: "힌트를 볼까요? 힌트를 보고 다시 해 보세요.",
      sendHint: true,
      sendAnswer: false,
      needsRebuild: false,
      xpEarned: 0,
      stars: 0,
    };
  }

  // 1~2회 오답 - 안내만 한다.
  return {
    state: { ...prev, wrongCount },
    action: "retry",
    message: WRONG_MESSAGES[wrongCount - 1],
    sendHint: false,
    sendAnswer: false,
    needsRebuild: false,
    xpEarned: 0,
    stars: 0,
  };
}

/**
 * 학생 세션 · PIN 보안.
 *
 * AI 면담실(GAS)의 방식을 그대로 옮겨 왔다.
 *   · PIN 은 서버 비밀키를 섞은 해시로만 대조한다.
 *   · 세션 토큰은 base64url(payload) + "." + 서명 형태다.
 *   · PIN 을 여러 번 틀리면 잠시 잠근다.
 *
 * 비밀키는 Supabase Secret 에만 있다:
 *   supabase secrets set APP_SESSION_SECRET=<충분히 긴 무작위 문자열>
 */

export const SESSION_HOURS = 12;
export const PIN_MAX_FAILED_ATTEMPTS = 5;
export const PIN_LOCK_MINUTES = 10;

export interface SessionPayload {
  /** student id */
  sid: string;
  /** class id */
  cid: string;
  /** 발급 시각 (ISO) */
  iat: string;
  /** 만료 시각 (ISO) */
  exp: string;
}

function requireSecret(): string {
  const secret = Deno.env.get("APP_SESSION_SECRET");
  if (!secret || secret.length < 16) {
    throw new Error(
      "APP_SESSION_SECRET 이 설정되지 않았습니다. supabase secrets set APP_SESSION_SECRET=... 을 실행하세요.",
    );
  }
  return secret;
}

const encoder = new TextEncoder();

async function hmacHex(message: string): Promise<string> {
  const key = await crypto.subtle.importKey(
    "raw",
    encoder.encode(requireSecret()),
    { name: "HMAC", hash: "SHA-256" },
    false,
    ["sign"],
  );
  const signature = await crypto.subtle.sign("HMAC", key, encoder.encode(message));
  return [...new Uint8Array(signature)].map((b) => b.toString(16).padStart(2, "0")).join("");
}

export function normalizePin(pin: unknown): string {
  const text = String(pin ?? "").replace(/\D/g, "");
  return text.slice(0, 4).padStart(4, "0");
}

export function isValidPinFormat(pin: unknown): boolean {
  return /^\d{4}$/.test(String(pin ?? "").trim());
}

/** PIN 대조용 해시. 원문은 어디에도 남기지 않는다. */
export function hashPin(studentId: string, pin: string): Promise<string> {
  return hmacHex(`pin:v1:${studentId}:${normalizePin(pin)}`);
}

/** 4자리 PIN 을 만든다. 0000, 1234 같이 알아맞히기 쉬운 값은 피한다. */
export function generatePin(): string {
  const weak = new Set(["0000", "1111", "2222", "3333", "4444", "5555", "6666", "7777", "8888", "9999", "1234", "4321", "0123"]);
  for (let i = 0; i < 50; i++) {
    const bytes = new Uint32Array(1);
    crypto.getRandomValues(bytes);
    const pin = String(bytes[0] % 10000).padStart(4, "0");
    if (!weak.has(pin)) return pin;
  }
  return "8642";
}

function base64UrlEncode(text: string): string {
  return btoa(String.fromCharCode(...encoder.encode(text)))
    .replace(/\+/g, "-")
    .replace(/\//g, "_")
    .replace(/=+$/, "");
}

function base64UrlDecode(text: string): string {
  const padded = text.replace(/-/g, "+").replace(/_/g, "/") + "=".repeat((4 - (text.length % 4)) % 4);
  return new TextDecoder().decode(Uint8Array.from(atob(padded), (c) => c.charCodeAt(0)));
}

export async function issueSessionToken(
  studentId: string,
  classId: string,
): Promise<{ token: string; tokenHash: string; payload: SessionPayload }> {
  const now = Date.now();
  const payload: SessionPayload = {
    sid: studentId,
    cid: classId,
    iat: new Date(now).toISOString(),
    exp: new Date(now + SESSION_HOURS * 60 * 60 * 1000).toISOString(),
  };

  const encoded = base64UrlEncode(JSON.stringify(payload));
  const signature = await hmacHex(`session:v1:${encoded}`);
  const token = `${encoded}.${signature}`;

  return { token, tokenHash: await hashToken(token), payload };
}

/** 표에는 토큰 원문이 아니라 해시를 저장한다. */
export function hashToken(token: string): Promise<string> {
  return hmacHex(`token:v1:${token}`);
}

/** 서명과 만료를 확인한다. 표에 남은 세션 확인은 호출하는 쪽에서 따로 한다. */
export async function verifySessionToken(token: unknown): Promise<SessionPayload | null> {
  const text = String(token ?? "").trim();
  const dot = text.indexOf(".");
  if (dot <= 0) return null;

  const encoded = text.slice(0, dot);
  const signature = text.slice(dot + 1);
  const expected = await hmacHex(`session:v1:${encoded}`);

  // 길이가 다르면 그대로 실패. 같으면 상수 시간 비교.
  if (signature.length !== expected.length) return null;
  let diff = 0;
  for (let i = 0; i < signature.length; i++) diff |= signature.charCodeAt(i) ^ expected.charCodeAt(i);
  if (diff !== 0) return null;

  try {
    const payload = JSON.parse(base64UrlDecode(encoded)) as SessionPayload;
    if (!payload.sid || !payload.cid || !payload.exp) return null;
    const expiry = new Date(payload.exp).getTime();
    if (!Number.isFinite(expiry) || expiry <= Date.now()) return null;
    return payload;
  } catch {
    return null;
  }
}

/** 학급 접속 코드. 헷갈리는 글자(O/0, I/1)를 뺐다. */
export function generateClassCode(length = 5): string {
  const alphabet = "ABCDEFGHJKLMNPQRSTUVWXYZ23456789";
  const bytes = new Uint8Array(length);
  crypto.getRandomValues(bytes);
  return [...bytes].map((b) => alphabet[b % alphabet.length]).join("");
}

/** 9차시 문제 공유 코드. */
export function generateShareCode(): string {
  return generateClassCode(6);
}

/** Edge Function 공통 응답 처리. */

export const CORS_HEADERS: Record<string, string> = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Headers": "authorization, x-client-info, apikey, content-type, x-student-token",
  "Access-Control-Allow-Methods": "POST, OPTIONS",
};

export function json(status: number, body: unknown): Response {
  return new Response(JSON.stringify(body), {
    status,
    headers: { ...CORS_HEADERS, "content-type": "application/json; charset=utf-8" },
  });
}

export function ok(body: unknown): Response {
  return json(200, body);
}

export function fail(status: number, code: string, message: string): Response {
  return json(status, { error: { code, message } });
}

export function handlePreflight(req: Request): Response | null {
  if (req.method === "OPTIONS") return new Response("ok", { headers: CORS_HEADERS });
  return null;
}

export async function readJson(req: Request): Promise<Record<string, unknown>> {
  try {
    const body = await req.json();
    return body && typeof body === "object" ? (body as Record<string, unknown>) : {};
  } catch {
    return {};
  }
}

export function text(value: unknown, max = 200): string {
  return String(value ?? "").trim().slice(0, max);
}

